{
  "items": [
    {
      "name": "AddMonoidAlgebra.infDegree",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "abbrev",
      "type": "{R : Type u_1} →\n  {A : Type u_3} →\n    {T : Type u_4} →\n      [inst : Semiring R] → [inst_1 : SemilatticeInf T] → [OrderTop T] → (A → T) → AddMonoidAlgebra R A → T"
    },
    {
      "name": "AddMonoidAlgebra.le_inf_support_pow",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {T : Type u_4} [inst : SemilatticeInf T] [inst_1 : OrderTop T] [inst_2 : Semiring R]\n  [inst_3 : AddMonoid A] [inst_4 : AddMonoid T] [AddLeftMono T] [AddRightMono T] {degt : A → T},\n  0 ≤ degt 0 →\n    (∀ (a b : A), degt a + degt b ≤ degt (a + b)) →\n      ∀ (n : ℕ) (f : AddMonoidAlgebra R A), n • f.support.inf degt ≤ (f ^ n).support.inf degt"
    },
    {
      "name": "AddMonoidAlgebra.apply_eq_zero_of_not_le_supDegree",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {B : Type u_5} [inst : Semiring R] [inst_1 : SemilatticeSup B] [inst_2 : OrderBot B]\n  {D : A → B} {p : AddMonoidAlgebra R A} {a : A}, ¬D a ≤ AddMonoidAlgebra.supDegree D p → p a = 0"
    },
    {
      "name": "AddMonoidAlgebra.le_inf_support_finset_prod",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {T : Type u_4} {ι : Type u_6} [inst : SemilatticeInf T] [inst_1 : OrderTop T]\n  [inst_2 : CommSemiring R] [inst_3 : AddCommMonoid A] [inst_4 : AddCommMonoid T] [AddLeftMono T] [AddRightMono T]\n  {degt : A → T},\n  0 ≤ degt 0 →\n    (∀ (a b : A), degt a + degt b ≤ degt (a + b)) →\n      ∀ (s : Finset ι) (f : ι → AddMonoidAlgebra R A), ∑ i ∈ s, (f i).support.inf degt ≤ (∏ i ∈ s, f i).support.inf degt"
    },
    {
      "name": "AddMonoidAlgebra.supDegree_sum_lt",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {B : Type u_5} [inst : Semiring R] [inst_1 : LinearOrder B] [inst_2 : OrderBot B]\n  {D : A → B} {ι : Type u_7} {s : Finset ι} {f : ι → AddMonoidAlgebra R A},\n  s.Nonempty →\n    ∀ {b : B}, (∀ i ∈ s, AddMonoidAlgebra.supDegree D (f i) < b) → AddMonoidAlgebra.supDegree D (∑ i ∈ s, f i) < b"
    },
    {
      "name": "AddMonoidAlgebra.le_infDegree_mul",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {T : Type u_4} [inst : Semiring R] [inst_1 : SemilatticeInf T] [inst_2 : OrderTop T]\n  [inst_3 : AddZeroClass A] [inst_4 : Add T] [AddLeftMono T] [AddRightMono T] (D : A →ₙ+ T)\n  (f g : AddMonoidAlgebra R A),\n  AddMonoidAlgebra.infDegree (⇑D) f + AddMonoidAlgebra.infDegree (⇑D) g ≤ AddMonoidAlgebra.infDegree (⇑D) (f * g)"
    },
    {
      "name": "AddMonoidAlgebra.supDegree_add_eq_left",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {B : Type u_5} [inst : Semiring R] [inst_1 : LinearOrder B] [inst_2 : OrderBot B]\n  {p q : AddMonoidAlgebra R A} {D : A → B} [inst_3 : AddZeroClass A],\n  AddMonoidAlgebra.supDegree D q < AddMonoidAlgebra.supDegree D p →\n    AddMonoidAlgebra.supDegree D (p + q) = AddMonoidAlgebra.supDegree D p"
    },
    {
      "name": "AddMonoidAlgebra.le_infDegree_add",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {T : Type u_4} [inst : Semiring R] [inst_1 : SemilatticeInf T] [inst_2 : OrderTop T]\n  (D : A → T) (f g : AddMonoidAlgebra R A),\n  AddMonoidAlgebra.infDegree D f ⊓ AddMonoidAlgebra.infDegree D g ≤ AddMonoidAlgebra.infDegree D (f + g)"
    }
  ]
}
